def transfer(db, tenant, key, source, target, amount, checkpoint=lambda: None):
    if type(amount) is not int or amount <= 0 or source == target:
        raise ValueError('invalid transfer')
    with db:
        old = db.execute('SELECT source,target,amount FROM transfers WHERE tenant=? AND request_key=?', (tenant,key)).fetchone()
        if old:
            if old != (source,target,amount):
                raise ValueError('key conflict')
            return old[2]
        balances = {}
        for account in (source,target):
            row=db.execute('SELECT balance FROM accounts WHERE tenant=? AND account=?',(tenant,account)).fetchone()
            if row is None:
                raise ValueError('missing account')
            balances[account]=row[0]
        if balances[source] < amount:
            raise ValueError('insufficient funds')
        db.execute('UPDATE accounts SET balance=balance-? WHERE tenant=? AND account=?',(amount,tenant,source))
        checkpoint()
        db.execute('UPDATE accounts SET balance=balance+? WHERE tenant=? AND account=?',(amount,tenant,target))
        db.execute('INSERT INTO transfers VALUES (?,?,?,?,?,?)',(tenant,key,source,target,amount,'done'))
